for (const id in T) {
  if (L['tech.' + id]) continue;
  if (T[id].ageUp) L['tech.' + id] = L['age.' + T[id].ageUp];
  else { const f = T[id].fx.find(x => x.t === 'line'); if (f) L['tech.' + id] = L['unit.' + f.to]; }
}
